// An external producer: it knows only the published Forma workflow schema.
// No Forma code, no Forma Studio. It writes forma/workflows/<id>.forma-workflow.json.
//   node produce.mjs <output-directory>
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const out = process.argv[2] ?? ".";
const workflow = {
  $schema: "https://forma.echelonfoundry.com/schemas/workflow/1.0/forma-workflow.schema.json",
  format: "forma-workflow",
  formatVersion: "1.0.0",
  id: "mission-handoff",
  title: "Mission handoff",
  description: "Generated by a ground-segment scheduler without any coordinates.",
  forma: { version: "0.4.0" },
  metadata: { generator: "ground-scheduler", shift: "B", budgetHours: 12.50, tags: ["handoff", "ops"] },
  nodes: [
    { id: "brief", kind: "start", label: "Shift briefing", status: { state: "complete" },
      metadata: { room: "MOCR-2", attendees: 14 } },
    { id: "checklist", kind: "task", label: "Handoff checklist",
      color: { fill: "#e8f0ff", accent: "#2f5fb3", foreground: "#1d1d1b" },
      references: [{ id: "proc", system: "org.example.procedures", type: "Procedure", key: "OPS-118", label: "Procedure OPS-118", href: "https://example.org/ops/118" }],
      extensions: { "org.example.scheduler": { slot: 7, crew: ["A", "B"], window: { start: "06:00", end: "06:30" } } } },
    { id: "anomalies", kind: "decision", label: "Open anomalies?" },
    { id: "review", kind: "org.example.scheduler:joint-review", kindLabel: "Joint review", label: "Joint anomaly review",
      status: { state: "org.example.scheduler:scheduled", label: "Scheduled" } },
    { id: "accept", kind: "end", label: "Shift accepted" }
  ],
  edges: [
    { id: "h1", source: { node: "brief" }, target: { node: "checklist" } },
    { id: "h2", source: { node: "checklist" }, target: { node: "anomalies" } },
    { id: "h3", source: { node: "anomalies" }, target: { node: "review" }, kind: "conditional", label: "Yes",
      metadata: { priority: 1 }, extensions: { "org.example.scheduler": { escalation: true } } },
    { id: "h4", source: { node: "anomalies" }, target: { node: "accept" }, kind: "conditional", label: "No" },
    { id: "h5", source: { node: "review" }, target: { node: "accept" }, line: "dashed" }
  ],
  groups: [{ id: "outgoing", kind: "swimlane", label: "Outgoing shift", members: ["brief", "checklist"] }],
  extensions: { "org.example.scheduler": { run: "2026-10-01T06:00:00Z", version: "4.2.0" } },
  provenance: { producer: { name: "ground-scheduler", version: "4.2.0" } }
};
const dir = join(out, "forma", "workflows");
mkdirSync(dir, { recursive: true });
const file = join(dir, `${workflow.id}.forma-workflow.json`);
writeFileSync(file, JSON.stringify(workflow, null, 2) + "\n");
console.log(file);
